# Delfinora (Carpathia No. 10130) sculpted from nothing on the skeleton and clips of the game's own export of it
# (sculptkit.py); the game has no sculptor for it, so its export is a body generated by rule and only its bones,
# clips and size are kept:
#   blender --background --factory-startup --python sculpts/delfinora.py -- <the export's Delfinora.glb> <out.glb>
#
# Grown from delfinel.py (its frame, fins, fluke, curled dorsal and eyes, through sibling("delfinel")). From the
# picture (10130-Delfinora.jpg) and the brief (CP-dex-3, "130. Delfinora"): a sleek, graceful dolphin in deep sea-blue
# with a pale cream belly running from the lower jaw to the tail; a longer beak and a calm closed smile; calm almond
# eyes; a glowing pale crescent on the forehead; an hourglass of yellow edged in grey on each flank with a few yellow
# dots; a tall dorsal fin swept back and hooked at its tip; long pectoral fins; and in place of a plain fluke a gown of
# long flowing ribbons in blue, yellow and grey. The picture's rings of psychic light are a drawn effect and dropped;
# its leap is not the rest pose: it swims level at the export's height.
import os, sys, math
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
import numpy as np
from sculptkit import (Kit, ell, tube, sheet, slab, srgb, inside, unit, polygon, eye_look, outward, args, sibling)

dl = sibling("delfinel")
BLUE, BLUE_DARK, CREAM, YELLOW, GREYB = "#2D6B87", "#1F4E66", "#F1EBCB", "#F2E37A", "#AEB5B8"
GLOW = "#F8F2B8"
IRIS, PUPIL, INK = srgb("#2A4E5E"), srgb("#10181E"), srgb("#14202A")


def almond_eye(u, v):
    """A calm eye: a dark teal iris filling the almond, a black pupil and a glint."""
    c = np.tile(IRIS, (len(u), 1))
    c[((u + 0.08) / 0.4) ** 2 + ((v + 0.05) / 0.62) ** 2 < 1] = PUPIL
    c[np.hypot(u + 0.25, v - 0.25) < 0.22] = (1.0, 1.0, 1.0)
    return c


ALMOND = polygon([(1.0, 0.1), (0.7, 0.55), (0.2, 0.75), (-0.4, 0.62), (-0.85, 0.3), (-1.0, -0.05), (-0.7, -0.5),
                  (-0.1, -0.75), (0.5, -0.6), (0.9, -0.3)])


def ribbon(k, name, root, d, L, w, color, phase, rise=0.0):
    """One ribbon of the gown: a strip flowing back and down from root along d, waving, widening then tapering."""
    root, d = np.array(root, float), unit(*d)
    across = np.cross(d, (0, 0, 1.0)); across /= np.linalg.norm(across)
    across = unit(*(across + np.array([0, 0, rise])))
    def at(u, v):
        uu = 0.01 + 0.98 * u
        c = (root[None, None, :] + d[None, None, :] * (L * uu)[..., None]
             + np.array([0, 0, -1.0])[None, None, :] * (0.08 * L * uu ** 1.5)[..., None]
             + across[None, None, :] * (0.022 * np.sin(2.6 * np.pi * uu + phase) * uu)[..., None])
        half = w * (0.7 + 0.8 * uu) * (1 - 0.55 * uu ** 5)
        return c + across[None, None, :] * ((v - 0.5) * 2 * half)[..., None]
    k.add(name, outward(sheet(at, 40, 5, 0.011)), color, "tailFin", fuse=False, surface="scales")


def delfinora(src, out):
    k = Kit(src, coat="scales")
    # --- a sleek spindle: the head, the torso, the tail stock tapering behind ---------------------------------
    HC, HR = np.array([0, -0.14, 0.335]), np.array([0.114, 0.15, 0.12])
    k.add("head", ell(HC, HR, rot=(4, 0, 0)), BLUE, "body")
    k.add("torso", ell((0, 0.0, 0.315), (0.128, 0.2, 0.136)), BLUE, "body")
    k.add("rear", tube([(0, 0.1, 0.312), (0, 0.22, 0.306)], [0.106, 0.062], seg=32), BLUE, "body")
    k.add("stock", tube([(0, 0.22, 0.306), (0, 0.3, 0.302)], [0.062, 0.036], seg=32), BLUE, "tail")
    k.add("beak", ell((0, -0.3, 0.305), (0.046, 0.085, 0.036), rot=(8, 0, 0)), BLUE, "head")
    k.add("jaw", ell((0, -0.282, 0.276), (0.046, 0.08, 0.026), rot=(-6, 0, 0)), CREAM, "head")
    # --- fins: long pectorals, the tall swept dorsal hooked at its tip ---------------------------------------
    dl.pectorals(k, (0.1, -0.05, 0.22), (0.55, 0.45, -0.7), (0.13, 0.045, 0.016), BLUE)
    dl.curl_fin(k, (0.0, 0.03, 0.44), 1.12, BLUE, lean=38)
    # --- the gown: long ribbons in place of a fluke, fanning back and out, swept a little toward +X ------------
    cols = [BLUE, YELLOW, GREYB, BLUE_DARK, YELLOW, BLUE, GREYB, YELLOW, BLUE_DARK, YELLOW, BLUE]
    root = np.array([0, 0.295, 0.302])
    for i, a in enumerate(np.linspace(-0.95, 0.95, 11)):
        a = a + 0.2
        d = (math.sin(a) * 0.62, 0.3 + 0.08 * math.cos(a), -0.3)
        L = 0.29 + 0.04 * math.cos(a * 2.2) + 0.025 * (i % 2)
        ribbon(k, f"ribbon{i}", root + (0.01 * math.sin(a), 0, 0.006 * (i % 3)), d, L, 0.031, cols[i], i * 1.3,
               rise=0.2 * math.sin(a))
    k.add("gowncap", ell(root, (0.04, 0.03, 0.035)), BLUE, "tail")
    # --- the pale belly, from the jaw along the underside ---------------------------------------------------
    edge = lambda y: np.interp(y, [-0.4, -0.22, -0.1, 0.05, 0.2, 0.32], [0.3, 0.3, 0.27, 0.24, 0.265, 0.295])
    k.paint(lambda P: inside(P[:, 2] - edge(P[:, 1]), 0.004), CREAM, on=["head", "torso", "rear", "stock", "jaw"])
    # --- the hourglass on each flank: grey edged, yellow within, pinched in the middle ------------------------
    def hourglass(scale, reach):
        def m(P):
            ty = (P[:, 1] - 0.035) / (0.12 * reach)
            zc = 0.355 - 0.035 * ty
            h = 0.05 * scale * (0.35 + 0.65 * np.abs(ty) ** 0.9) * np.sqrt(np.clip(1 - ty * ty, 0, 1))
            return inside(np.abs(P[:, 2] - zc) - h, 0.003) * (np.abs(ty) < 1) * (np.abs(P[:, 0]) > 0.04)
        return m
    k.paint(hourglass(1.35, 1.15), GREYB)
    k.paint(hourglass(0.85, 0.92), YELLOW)
    for sx in (1, -1):
        for y, z in ((-0.06, 0.4), (-0.035, 0.415), (0.02, 0.385)):
            k.decal((0.12 * sx, y, z), unit(sx, 0, 0.6), (0.011, 0.011), YELLOW, eps=0.003, rings=6, segs=28)
    # --- a calm closed smile: a thin dark line where the beak meets the pale jaw at the front ----------------
    k.decal((0, -0.37, 0.29), unit(0, -1, -0.15), (0.03, 0.007), "#1A2630", up=(0, 0, 1), eps=0.003,
            outline=polygon([(-1, 0.6), (0, -0.4), (1, 0.6), (0.9, 1.0), (0, 0.4), (-0.9, 1.0)]), rings=6, segs=48)
    # --- the glowing crescent on the forehead, turned a little toward +X --------------------------------------
    dn = unit(0.32, -0.6, 0.73)
    c = dl.at_surface(HC, HR, dn) + dn * 0.004
    ex = unit(*np.cross((0, 0, 1.0), dn)) * -1
    ez = unit(*np.cross(dn, ex))
    R = 0.046
    outer = [(R * math.cos(t), R * math.sin(t)) for t in np.radians(np.linspace(200, 340, 12))]
    inner = [(R * 0.82 * math.cos(t), R * 0.82 * math.sin(t) + 0.45 * R) for t in np.radians(np.linspace(338, 202, 12))]
    k.add("crescent", slab(outer + inner, c, ex, ez, 0.008), GLOW, "head", fuse=False, glow=GLOW, surface="skin")
    # --- the eyes: calm almonds high on the head --------------------------------------------------------------
    de = unit(0.62, -0.62, 0.45)
    E = dl.at_surface(HC, HR, de)
    k.build(voxel=0.0055, smooth=4, band=0.008, wband=0.05)
    k.eye_states(dl.lay_eyes(k, E, de, (0.044, 0.034), BLUE, almond_eye, ALMOND))
    k.export(out)


if __name__ == "__main__":
    delfinora(*args())
